changeSet.sql:
INSERT INTO product_attributes (product_id, field_key, value_text) SELECT rpd.product_id, 'size', trim(rpd.clothing_size_range) FROM retail_product_details rpd WHERE rpd.clothing_size_range IS NOT NULL AND trim(rpd.clothing_size_range) <> '' ON CONFLICT (product_id, field_key) DO NOTHING;
INSERT INTO product_attributes (product_id, field_key, value_text) SELECT rpd.product_id, 'color', trim(rpd.clothing_color) FROM retail_product_details rpd WHERE rpd.clothing_color IS NOT NULL AND trim(rpd.clothing_color) <> '' ON CONFLICT (product_id, field_key) DO NOTHING;
INSERT INTO product_attributes (product_id, field_key, value_text) SELECT rpd.product_id, 'gender', trim(rpd.clothing_gender) FROM retail_product_details rpd WHERE rpd.clothing_gender IS NOT NULL AND trim(rpd.clothing_gender) <> '' ON CONFLICT (product_id, field_key) DO NOTHING;
INSERT INTO product_attributes (product_id, field_key, value_text) SELECT rpd.product_id, 'dosage_form', trim(rpd.pharmacy_dosage_form) FROM retail_product_details rpd WHERE rpd.pharmacy_dosage_form IS NOT NULL AND trim(rpd.pharmacy_dosage_form) <> '' ON CONFLICT (product_id, field_key) DO NOTHING;
INSERT INTO product_attributes (product_id, field_key, value_text) SELECT rpd.product_id, 'prescription_required', 'true' FROM retail_product_details rpd WHERE rpd.pharmacy_prescription_required = TRUE ON CONFLICT (product_id, field_key) DO NOTHING;
INSERT INTO product_attributes (product_id, field_key, value_text) SELECT rpd.product_id, 'expiry_tracking', 'true' FROM retail_product_details rpd WHERE rpd.pharmacy_expiry_required = TRUE ON CONFLICT (product_id, field_key) DO NOTHING;
